select 'legislacao-crimes-ciberneticos-atualizado-2026','Legislação Penal Especial','Crimes cibernéticos, invasão e fraude eletrônica',251,'Crimes cibernéticos: invasão, fraude eletrônica e penas atualizadas','Revisão dos arts. 154-A e 154-B, furto eletrônico, fraude eletrônica, divulgação de cenas íntimas e falsificação de cartões, com alterações até 2026.','## Invasão de dispositivo — arts. 154-A e 154-B

A Lei nº 12.737/2012 introduziu os arts. 154-A e 154-B. A redação do art. 154-A foi alterada pela Lei nº 14.155/2021. Na redação vigente, o tipo envolve invadir dispositivo informático alheio, conectado ou não à rede, com a finalidade de obter, adulterar ou destruir dados sem autorização, ou instalar vulnerabilidades para obter vantagem ilícita.

- **Pena básica:** reclusão de 1 a 4 anos e multa.
- **Prejuízo econômico:** aumento de 1/3 a 2/3.
- **Ação penal:** em regra, mediante representação, ressalvadas hipóteses legais relativas à Administração Pública e concessionárias de serviço público.

**Pegadinha:** o texto original da Lei nº 12.737/2012 previa pena menor e exigia violação de mecanismo de segurança. Não reproduza esse texto antigo como redação atual.

## Furto eletrônico e fraude eletrônica

- **Furto eletrônico (art. 155, § 4º-B):** após a Lei nº 15.397/2026, pena de reclusão de **4 a 10 anos** e multa.
- **Fraude eletrônica (art. 171, § 2º-A):** pena de reclusão de **4 a 8 anos** e multa. A Lei nº 14.155/2021 também alterou regras de competência do CPP para determinadas modalidades de estelionato.

## Outros dispositivos

- **Falsificação de cartão:** o art. 298, parágrafo único, equipara cartão de crédito ou débito a documento particular.
- **Divulgação de cenas íntimas (art. 218-C):** abrange divulgação por qualquer meio — inclusive sistema informático ou telemático — de cena de estupro ou estupro de vulnerável e, sem consentimento, de cena de sexo, nudez ou pornografia. Após a Lei nº 15.280/2025, a pena é de reclusão de **4 a 10 anos e multa**, se o fato não constitui crime mais grave.
- Crimes contra a honra, extorsão e outros delitos podem ocorrer em ambiente digital, mas não se confundem automaticamente com invasão de dispositivo.

**Fontes oficiais:** [Código Penal compilado](https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm), [Lei nº 12.737/2012](https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12737.htm), [Lei nº 14.155/2021](https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14155.htm), [Lei nº 15.280/2025](https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15280.htm) e [Lei nº 15.397/2026](https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15397.htm).','Polícia Civil do Estado do Paraná — Agente de Polícia Judiciária — Edital 01/2026',1,'Material autoral vinculado ao tópico ativo do Edital 01/2026 PC-PR sobre crimes cibernéticos, fraudes eletrônicas e invasão de dispositivos. Fontes oficiais conferidas em 24/10/2026; consideradas as Leis nº 14.155/2021, 15.280/2025 e 15.397/2026.','[{"url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal compilado"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12737.htm","title":"Lei nº 12.737/2012"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14155.htm","title":"Lei nº 14.155/2021"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15280.htm","title":"Lei nº 15.280/2025"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15397.htm","title":"Lei nº 15.397/2026"}]'::jsonb,now(),'active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6'::uuid,now(),'[{"b":"Reclusão de 1 a 4 anos e multa.","f":"Pena básica do art. 154-A?"},{"b":"Em regra, mediante representação, ressalvadas exceções legais.","f":"Regra de ação penal do art. 154-B?"},{"b":"Reclusão de 4 a 10 anos e multa, após a Lei nº 15.397/2026.","f":"Pena atual do furto eletrônico?"},{"b":"Reclusão de 4 a 10 anos e multa, se não houver crime mais grave.","f":"Pena atual do art. 218-C?"}]'::jsonb,'[{"a":true,"q":"Na forma básica vigente, o art. 154-A do Código Penal prevê reclusão de 1 a 4 anos e multa.","why":"Certo. Essa é a redação vigente após a Lei nº 14.155/2021; não use a pena original da Lei nº 12.737/2012."},{"a":false,"q":"A redação vigente do art. 154-A exige necessariamente violação de mecanismo de segurança.","why":"Errado. A Lei nº 14.155/2021 retirou esse requisito expresso; os demais elementos legais do tipo devem estar presentes."},{"a":false,"q":"O crime do art. 154-A é sempre processado sem representação, mesmo quando não envolve Administração Pública ou concessionária de serviço público.","why":"Errado. O art. 154-B prevê, em regra, ação mediante representação, com exceções legais específicas."},{"a":true,"q":"O furto eletrônico do art. 155, § 4º-B, tem pena vigente de 4 a 10 anos e multa.","why":"Certo. A Lei nº 15.397/2026 elevou a pena dessa modalidade para 4 a 10 anos e multa."},{"a":true,"q":"A fraude eletrônica do art. 171, § 2º-A, prevê pena de reclusão de 4 a 8 anos e multa.","why":"Certo. Essa faixa permanece na redação vigente; não confunda com a pena do furto eletrônico, alterada em 2026."},{"a":false,"q":"A pena original de detenção de 3 meses a 1 ano, prevista no texto inicial da Lei nº 12.737/2012, continua sendo a pena básica atual da invasão.","why":"Errado. A pena foi alterada pela Lei nº 14.155/2021; a pena básica atual é reclusão de 1 a 4 anos e multa."},{"a":true,"q":"O art. 218-C abrange divulgação por qualquer meio, inclusive internet, de cenas de estupro e, sem consentimento, de cenas de sexo, nudez ou pornografia; a pena atual é de 4 a 10 anos e multa, se não houver crime mais grave.","why":"Certo. A Lei nº 15.280/2025 alterou a pena do art. 218-C para reclusão de 4 a 10 anos e multa."},{"a":true,"q":"Para fins do art. 298 do Código Penal, cartão de crédito ou débito é equiparado a documento particular.","why":"Certo. Essa equiparação foi incluída pela Lei nº 12.737/2012."}]'::jsonb,'{"scope":"Legislação penal federal para tópico ativo de crimes cibernéticos do Edital 01/2026 PC-PR.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15397.htm","state":"effective","title":"Lei nº 15.397/2026","summary":"Furto eletrônico: pena de 4 a 10 anos."},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15280.htm","state":"effective","title":"Lei nº 15.280/2025","summary":"Art. 218-C: pena de 4 a 10 anos."}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal compilado"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12737.htm","title":"Lei nº 12.737/2012"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14155.htm","title":"Lei nº 14.155/2021"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15280.htm","title":"Lei nº 15.280/2025"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15397.htm","title":"Lei nº 15.397/2026"}],"checked_at":"2026-10-24T20:50:00Z","corrections":[]}'::jsonb,'{"items":[{"a":true,"q":"Na forma básica vigente, o art. 154-A do Código Penal prevê reclusão de 1 a 4 anos e multa.","why":"Certo. Essa é a redação vigente após a Lei nº 14.155/2021; não use a pena original da Lei nº 12.737/2012.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":false,"q":"A redação vigente do art. 154-A exige necessariamente violação de mecanismo de segurança.","why":"Errado. A Lei nº 14.155/2021 retirou esse requisito expresso; os demais elementos legais do tipo devem estar presentes.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14155.htm"},{"a":false,"q":"O crime do art. 154-A é sempre processado sem representação, mesmo quando não envolve Administração Pública ou concessionária de serviço público.","why":"Errado. O art. 154-B prevê, em regra, ação mediante representação, com exceções legais específicas.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":true,"q":"O furto eletrônico do art. 155, § 4º-B, tem pena vigente de 4 a 10 anos e multa.","why":"Certo. A Lei nº 15.397/2026 elevou a pena dessa modalidade para 4 a 10 anos e multa.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15397.htm"},{"a":true,"q":"A fraude eletrônica do art. 171, § 2º-A, prevê pena de reclusão de 4 a 8 anos e multa.","why":"Certo. Essa faixa permanece na redação vigente; não confunda com a pena do furto eletrônico, alterada em 2026.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":false,"q":"A pena original de detenção de 3 meses a 1 ano, prevista no texto inicial da Lei nº 12.737/2012, continua sendo a pena básica atual da invasão.","why":"Errado. A pena foi alterada pela Lei nº 14.155/2021; a pena básica atual é reclusão de 1 a 4 anos e multa.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12737.htm"},{"a":true,"q":"O art. 218-C abrange divulgação por qualquer meio, inclusive internet, de cenas de estupro e, sem consentimento, de cenas de sexo, nudez ou pornografia; a pena atual é de 4 a 10 anos e multa, se não houver crime mais grave.","why":"Certo. A Lei nº 15.280/2025 alterou a pena do art. 218-C para reclusão de 4 a 10 anos e multa.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15280.htm"},{"a":true,"q":"Para fins do art. 298 do Código Penal, cartão de crédito ou débito é equiparado a documento particular.","why":"Certo. Essa equiparação foi incluída pela Lei nº 12.737/2012.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12737.htm"}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14155.htm"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15397.htm"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12737.htm"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15280.htm"}],"catalog_status":"eligible_active_current_syllabus","pending_item_indexes":[],"catalogued_item_indexes":[1,2,3,4,5,6,7,8]}'::jsonb where not exists(select 1 from public.study_materials where slug='legislacao-crimes-ciberneticos-atualizado-2026');
insert into public.study_materials(slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,law_version_checked_at,content_status,reviewed_by,reviewed_at,flashcards,quiz,legal_review,practice_review)
select 'legislacao-lgpd-atualizada-2026','Proteção de Dados Pessoais (LGPD)','LGPD: tratamento, segurança e ANPD',1,'LGPD: tratamento de dados, segurança e atualizações da ANPD','Conceitos, bases legais, tratamento pelo poder público, segurança e mudanças institucionais introduzidas pela Lei nº 15.352/2026.','## 1. Âmbito e conceitos

A Lei nº 13.709/2018 regula operações de tratamento de dados pessoais, inclusive em meios digitais, por pessoas naturais e jurídicas, públicas ou privadas, observadas suas hipóteses de aplicação e exceções.

- **Dado pessoal:** informação relacionada a pessoa natural identificada ou identificável.
- **Dado pessoal sensível:** inclui origem racial ou étnica, convicção religiosa, opinião política, filiação sindical, dados de saúde ou vida sexual e dados genéticos ou biométricos vinculados a pessoa natural.
- **Controlador:** toma decisões referentes ao tratamento.
- **Operador:** realiza o tratamento em nome do controlador.
- **Encarregado:** atua como canal de comunicação conforme a redação legal vigente.

## 2. Princípios e bases legais

O tratamento observa boa-fé e princípios como finalidade, adequação, necessidade, livre acesso, qualidade, transparência, segurança, prevenção, não discriminação e responsabilização. O **consentimento não é a única base legal**: o art. 7º prevê outras hipóteses, como obrigação legal, execução de contrato, políticas públicas e exercício regular de direitos. Para dados sensíveis, observe as bases específicas do art. 11.

## 3. Poder público e exceções

O capítulo IV disciplina o tratamento pelo poder público, incluindo finalidade pública, interesse público e competências legais. O art. 4º, III, exclui do regime ordinário operações para fins exclusivos de segurança pública, defesa nacional, segurança do Estado e investigação/repressão de infrações penais; o § 1º exige legislação específica com medidas proporcionais, devido processo, princípios de proteção e direitos do titular. **Exceção não significa ausência de limites.**

## 4. Segurança e responsabilização

O art. 46 exige medidas de segurança técnicas e administrativas para proteger dados contra acessos não autorizados e situações acidentais ou ilícitas. O art. 48 disciplina a comunicação de incidente de segurança que possa acarretar risco ou dano relevante, conforme os requisitos legais e a regulamentação aplicável.

A LGPD prevê consequências administrativas e civis; ela não cria, por si só, um crime geral de “vazamento de dados” com pena de prisão. Conforme os fatos, outras normas podem incidir.

## 5. Atualização de 2026: ANPD

A Lei nº 15.352/2026 alterou a LGPD quanto à estrutura da Autoridade Nacional de Proteção de Dados. O art. 55-A, na redação vigente, define a ANPD como **autarquia de natureza especial vinculada ao Ministério da Justiça e Segurança Pública**, com autonomia funcional, técnica, decisória, administrativa e financeira. Use o texto compilado, não apostilas antigas.

**Fontes oficiais:** [LGPD compilada](https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm) e [Lei nº 15.352/2026](https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15352.htm).','Controladoria-Geral do Município de Porto Velho (CGM/RO) — Auditor — 2026',1,'Material autoral vinculado ao tópico ativo da CGM/RO 2026 — Auditor, que prevê expressamente responsabilidade dos agentes de tratamento e tratamento de dados pelo poder público conforme a LGPD. Texto compilado e Lei nº 15.352/2026 conferidos em 24/10/2026.','[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm","title":"Lei nº 13.709/2018 — LGPD, texto compilado"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15352.htm","title":"Lei nº 15.352/2026 — alterações institucionais da ANPD"}]'::jsonb,now(),'active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6'::uuid,now(),'[{"b":"Informação relacionada a pessoa natural identificada ou identificável.","f":"O que é dado pessoal?"},{"b":"Não. O art. 7º prevê várias bases; dados sensíveis têm regras específicas no art. 11.","f":"Consentimento é a única base legal da LGPD?"},{"b":"O controlador toma decisões sobre o tratamento; o operador trata os dados em nome do controlador.","f":"Qual é a diferença entre controlador e operador?"},{"b":"Medidas de segurança técnicas e administrativas contra acessos não autorizados e situações acidentais ou ilícitas.","f":"O que exige o art. 46?"},{"b":"O art. 4º, III, exclui o tratamento exclusivamente penal do regime ordinário, mas exige legislação específica com salvaguardas.","f":"Como a LGPD trata investigação criminal?"}]'::jsonb,'[{"a":true,"q":"Para a LGPD, dado pessoal é informação relacionada a pessoa natural identificada ou identificável.","why":"Certo. É a definição do art. 5º, I, da Lei nº 13.709/2018."},{"a":true,"q":"Dados relativos à saúde, à vida sexual, à origem racial ou étnica e dados biométricos vinculados a pessoa natural podem ser dados pessoais sensíveis.","why":"Certo. Essas categorias estão abrangidas pelo art. 5º, II, da LGPD."},{"a":false,"q":"O consentimento é a única base legal possível para o tratamento de dados pessoais.","why":"Errado. O art. 7º prevê outras bases, como obrigação legal, execução de contrato, políticas públicas e exercício regular de direitos, conforme o caso."},{"a":true,"q":"O controlador toma decisões referentes ao tratamento; o operador realiza o tratamento em nome do controlador.","why":"Certo. Essa distinção consta das definições do art. 5º da LGPD."},{"a":false,"q":"A LGPD aplica-se apenas ao tratamento de dados armazenados em computadores e outros meios digitais.","why":"Errado. A lei abrange tratamento de dados pessoais inclusive nos meios digitais, sem limitar seu alcance a esses meios."},{"a":true,"q":"O tratamento para fins exclusivos de investigação e repressão de infrações penais fica fora do regime ordinário da LGPD, mas exige legislação específica com salvaguardas.","why":"Certo. É a regra do art. 4º, III e § 1º; a exceção não significa ausência de limites ou garantias."},{"a":true,"q":"O art. 46 da LGPD exige medidas de segurança técnicas e administrativas para proteger dados pessoais contra acessos não autorizados e situações ilícitas ou acidentais.","why":"Certo. O artigo exige medidas de segurança adequadas desde a concepção do produto ou serviço até sua execução."},{"a":true,"q":"A Lei nº 15.352/2026 alterou a LGPD para definir a ANPD como autarquia de natureza especial vinculada ao Ministério da Justiça e Segurança Pública.","why":"Certo. Essa é a redação vigente do art. 55-A, alterada pela Lei nº 15.352/2026."}]'::jsonb,'{"scope":"LGPD para tópico ativo da CGM/RO 2026 — Auditor, que menciona expressamente responsabilidade dos agentes e tratamento de dados pelo poder público.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15352.htm","state":"effective","title":"Lei nº 15.352/2026","summary":"Alterou a LGPD quanto à estrutura institucional da ANPD, incluindo o art. 55-A."}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm","title":"Lei nº 13.709/2018 — LGPD, texto compilado"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15352.htm","title":"Lei nº 15.352/2026 — alterações institucionais da ANPD"}],"checked_at":"2026-10-24T20:50:00Z","corrections":[]}'::jsonb,'{"items":[{"a":true,"q":"Para a LGPD, dado pessoal é informação relacionada a pessoa natural identificada ou identificável.","why":"Certo. É a definição do art. 5º, I, da Lei nº 13.709/2018.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm"},{"a":true,"q":"Dados relativos à saúde, à vida sexual, à origem racial ou étnica e dados biométricos vinculados a pessoa natural podem ser dados pessoais sensíveis.","why":"Certo. Essas categorias estão abrangidas pelo art. 5º, II, da LGPD.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm"},{"a":false,"q":"O consentimento é a única base legal possível para o tratamento de dados pessoais.","why":"Errado. O art. 7º prevê outras bases, como obrigação legal, execução de contrato, políticas públicas e exercício regular de direitos, conforme o caso.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm"},{"a":true,"q":"O controlador toma decisões referentes ao tratamento; o operador realiza o tratamento em nome do controlador.","why":"Certo. Essa distinção consta das definições do art. 5º da LGPD.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm"},{"a":false,"q":"A LGPD aplica-se apenas ao tratamento de dados armazenados em computadores e outros meios digitais.","why":"Errado. A lei abrange tratamento de dados pessoais inclusive nos meios digitais, sem limitar seu alcance a esses meios.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm"},{"a":true,"q":"O tratamento para fins exclusivos de investigação e repressão de infrações penais fica fora do regime ordinário da LGPD, mas exige legislação específica com salvaguardas.","why":"Certo. É a regra do art. 4º, III e § 1º; a exceção não significa ausência de limites ou garantias.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm"},{"a":true,"q":"O art. 46 da LGPD exige medidas de segurança técnicas e administrativas para proteger dados pessoais contra acessos não autorizados e situações ilícitas ou acidentais.","why":"Certo. O artigo exige medidas de segurança adequadas desde a concepção do produto ou serviço até sua execução.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm"},{"a":true,"q":"A Lei nº 15.352/2026 alterou a LGPD para definir a ANPD como autarquia de natureza especial vinculada ao Ministério da Justiça e Segurança Pública.","why":"Certo. Essa é a redação vigente do art. 55-A, alterada pela Lei nº 15.352/2026.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15352.htm"}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15352.htm"}],"catalog_status":"eligible_active_current_syllabus","pending_item_indexes":[],"catalogued_item_indexes":[1,2,3,4,5,6,7,8]}'::jsonb where not exists(select 1 from public.study_materials where slug='legislacao-lgpd-atualizada-2026');
insert into public.study_materials(slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,law_version_checked_at,content_status,reviewed_by,reviewed_at,flashcards,quiz,legal_review,practice_review)
select 'legislacao-marco-civil-internet-2026','Direito Digital','Marco Civil da Internet: registros, provedores e responsabilidade',1,'Marco Civil da Internet: registros, provedores e atualizações de 2026','Princípios, prazos de guarda de registros, acesso judicial, porta lógica de origem e responsabilidade de provedores após o STF e o Decreto nº 12.975/2026.','## 1. Princípios e direitos

A Lei nº 12.965/2014 estabelece princípios, garantias, direitos e deveres para o uso da internet. O art. 3º inclui proteção da privacidade, proteção dos dados pessoais, neutralidade de rede e segurança. A lei não cria um tipo penal geral chamado “crime cibernético”.

## 2. Guarda de registros

- **Registros de conexão (art. 13):** guarda por **1 ano**, sob sigilo e em ambiente controlado e seguro.
- **Registros de acesso a aplicações (art. 15):** nos casos legais, guarda por **6 meses** pelo provedor de aplicações constituído como pessoa jurídica e que atue profissionalmente com fins econômicos.
- **Disponibilização:** não confunda guarda com acesso. A lei prevê sigilo e, em regra, autorização judicial para disponibilizar registros, sem prejuízo de hipóteses legais específicas.

## 3. Decreto nº 12.975/2026

O decreto alterou o Decreto nº 8.771/2016. Entre os pontos de estudo estão a guarda da **porta lógica de origem** associada ao endereço IP quando necessária para identificar inequivocamente o terminal ou o próximo enlace de rede, deveres de representação legal no Brasil, canal de denúncia acessível, transparência e deveres de cuidado relativos a categorias de conteúdo ilícito definidas na norma.

## 4. Responsabilidade dos provedores e Tema 987 do STF

O STF reconheceu a **inconstitucionalidade parcial e progressiva** do art. 19. A tese distingue categorias de conteúdo e situações de responsabilização: não se deve ensinar o art. 19 como regra absoluta para todo conteúdo de terceiro; para crimes contra a honra, o STF manteve a aplicação do regime do art. 19, sem excluir a possibilidade de remoção por notificação extrajudicial. A decisão também trata de conteúdos ilícitos, anúncios pagos e redes artificiais de distribuição.

Responsabilidade civil de provedor não equivale a responsabilidade penal automática por cada publicação de usuário. Leia a tese completa do Tema 987 junto com a lei e a regulamentação vigente.

**Fontes oficiais:** [Marco Civil da Internet](https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l12965.htm), [Decreto nº 12.975/2026](https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/decreto/D12975.htm) e [STF — Tema 987](https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=987).','PC SC - Agente de Polícia Civil 2026',2,'Material autoral vinculado ao tópico atual do edital PC SC — Agente de Polícia Civil 2026 que prevê crimes cibernéticos e Marco Civil da Internet. Lei, decreto e tese do STF conferidos em 24/10/2026.','[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l12965.htm","title":"Lei nº 12.965/2014 — Marco Civil da Internet"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/decreto/D12975.htm","title":"Decreto nº 12.975/2026"},{"url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=987","title":"STF — Tema 987"}]'::jsonb,now(),'active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6'::uuid,now(),'[{"b":"1 ano, sob sigilo e em ambiente controlado e seguro.","f":"Qual é o prazo de guarda dos registros de conexão?"},{"b":"6 meses, nos casos e para os provedores definidos pela lei.","f":"Qual é o prazo do art. 15 para registros de acesso a aplicações?"},{"b":"Guarda associada ao IP quando necessária para identificar inequivocamente o terminal ou o próximo enlace.","f":"O que o Decreto nº 12.975/2026 prevê sobre a porta lógica?"},{"b":"Reconheceu a inconstitucionalidade parcial e progressiva do art. 19 e fixou distinções entre categorias de conteúdo e situações de responsabilidade.","f":"O que decidiu o STF no Tema 987?"}]'::jsonb,'[{"a":true,"q":"O Marco Civil estabelece princípios, garantias, direitos e deveres para o uso da internet, mas não cria um tipo penal geral chamado simplesmente ''crime cibernético''.","why":"Certo. A tipificação penal deve ser buscada no Código Penal ou em legislação penal específica."},{"a":true,"q":"O art. 13 do Marco Civil prevê guarda sigilosa dos registros de conexão por 1 ano.","why":"Certo. O art. 13 estabelece prazo de 1 ano em ambiente controlado e seguro."},{"a":true,"q":"O art. 15 prevê, nos casos legalmente definidos, guarda dos registros de acesso a aplicações por 6 meses.","why":"Certo. A regra alcança os provedores de aplicações que se enquadram nos requisitos legais."},{"a":false,"q":"O Marco Civil permite que qualquer autoridade receba todos os registros de acesso sem observar sigilo ou requisitos judiciais.","why":"Errado. A lei prevê sigilo e regras próprias para disponibilização dos registros, em regra com autorização judicial, sem prejuízo de hipóteses legais específicas."},{"a":true,"q":"O Decreto nº 12.975/2026 prevê guarda da porta lógica de origem associada ao IP quando necessária para identificação inequívoca do terminal ou do próximo enlace de rede.","why":"Certo. O decreto acrescentou essa previsão à regulamentação do Marco Civil."},{"a":false,"q":"Após o Tema 987 do STF, o art. 19 do Marco Civil continua sendo uma regra absoluta e idêntica para toda hipótese de conteúdo de terceiro.","why":"Errado. O STF reconheceu inconstitucionalidade parcial e progressiva do art. 19 e fixou distinções entre categorias de conteúdo e situações de responsabilidade."},{"a":true,"q":"Na tese do Tema 987, o regime do art. 19 permanece aplicável às alegações de crimes contra a honra, sem excluir a possibilidade de remoção por notificação extrajudicial.","why":"Certo. Essa distinção integra a tese fixada pelo STF; não se deve generalizar um regime para todo conteúdo."},{"a":false,"q":"O Marco Civil torna automaticamente o provedor de aplicação criminalmente responsável por todo conteúdo publicado por usuários.","why":"Errado. O Marco Civil disciplina principalmente direitos, deveres e responsabilidade civil; não estabelece responsabilidade penal automática por toda publicação de terceiro."}]'::jsonb,'{"scope":"Marco Civil para tópico ativo do edital PC SC 2026 que menciona expressamente a Lei nº 12.965/2014.","changes":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/decreto/D12975.htm","state":"effective","title":"Decreto nº 12.975/2026","summary":"Atualizou a regulamentação do Marco Civil, incluindo porta lógica de origem e deveres de provedores."},{"url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=987","state":"effective","title":"STF — Tema 987","summary":"Tese sobre inconstitucionalidade parcial e progressiva do art. 19; julgamento em 27/06/2025 e trânsito em julgado em 17/06/2026."}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l12965.htm","title":"Lei nº 12.965/2014 — Marco Civil da Internet"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/decreto/D12975.htm","title":"Decreto nº 12.975/2026"},{"url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=987","title":"STF — Tema 987"}],"checked_at":"2026-10-24T20:50:00Z","corrections":[]}'::jsonb,'{"items":[{"a":true,"q":"O Marco Civil estabelece princípios, garantias, direitos e deveres para o uso da internet, mas não cria um tipo penal geral chamado simplesmente ''crime cibernético''.","why":"Certo. A tipificação penal deve ser buscada no Código Penal ou em legislação penal específica.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l12965.htm"},{"a":true,"q":"O art. 13 do Marco Civil prevê guarda sigilosa dos registros de conexão por 1 ano.","why":"Certo. O art. 13 estabelece prazo de 1 ano em ambiente controlado e seguro.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l12965.htm"},{"a":true,"q":"O art. 15 prevê, nos casos legalmente definidos, guarda dos registros de acesso a aplicações por 6 meses.","why":"Certo. A regra alcança os provedores de aplicações que se enquadram nos requisitos legais.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l12965.htm"},{"a":false,"q":"O Marco Civil permite que qualquer autoridade receba todos os registros de acesso sem observar sigilo ou requisitos judiciais.","why":"Errado. A lei prevê sigilo e regras próprias para disponibilização dos registros, em regra com autorização judicial, sem prejuízo de hipóteses legais específicas.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l12965.htm"},{"a":true,"q":"O Decreto nº 12.975/2026 prevê guarda da porta lógica de origem associada ao IP quando necessária para identificação inequívoca do terminal ou do próximo enlace de rede.","why":"Certo. O decreto acrescentou essa previsão à regulamentação do Marco Civil.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/decreto/D12975.htm"},{"a":false,"q":"Após o Tema 987 do STF, o art. 19 do Marco Civil continua sendo uma regra absoluta e idêntica para toda hipótese de conteúdo de terceiro.","why":"Errado. O STF reconheceu inconstitucionalidade parcial e progressiva do art. 19 e fixou distinções entre categorias de conteúdo e situações de responsabilidade.","origin":"authored_current_official_text","source_url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=987"},{"a":true,"q":"Na tese do Tema 987, o regime do art. 19 permanece aplicável às alegações de crimes contra a honra, sem excluir a possibilidade de remoção por notificação extrajudicial.","why":"Certo. Essa distinção integra a tese fixada pelo STF; não se deve generalizar um regime para todo conteúdo.","origin":"authored_current_official_text","source_url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=987"},{"a":false,"q":"O Marco Civil torna automaticamente o provedor de aplicação criminalmente responsável por todo conteúdo publicado por usuários.","why":"Errado. O Marco Civil disciplina principalmente direitos, deveres e responsabilidade civil; não estabelece responsabilidade penal automática por toda publicação de terceiro.","origin":"authored_current_official_text","source_url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l12965.htm"}],"sources":[{"url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l12965.htm"},{"url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/decreto/D12975.htm"},{"url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=987"}],"catalog_status":"eligible_active_current_syllabus","pending_item_indexes":[],"catalogued_item_indexes":[1,2,3,4,5,6,7,8]}'::jsonb where not exists(select 1 from public.study_materials where slug='legislacao-marco-civil-internet-2026');

with item_rows as (
 select sm.slug,sm.discipline,sm.topic_label,i.item,i.ord,
 case sm.slug when 'legislacao-crimes-ciberneticos-atualizado-2026' then '416e6d1d-62aa-4d1b-8808-acdf02b5ca1f'::uuid when 'legislacao-marco-civil-internet-2026' then 'c9ef51e3-73ea-4b8c-bed9-a7676d464787'::uuid when 'legislacao-lgpd-atualizada-2026' then 'b49fffef-e28d-4bff-b22d-a66e77637b24'::uuid end topic_id,
 case sm.slug when 'legislacao-crimes-ciberneticos-atualizado-2026' then 'PR' when 'legislacao-marco-civil-internet-2026' then 'SC' when 'legislacao-lgpd-atualizada-2026' then 'RO' end state
 from public.study_materials sm cross join lateral jsonb_array_elements(sm.practice_review->'items') with ordinality i(item,ord)
 where sm.slug in ('legislacao-crimes-ciberneticos-atualizado-2026','legislacao-marco-civil-internet-2026','legislacao-lgpd-atualizada-2026')
), eligible as (
 select ir.*,s.id source_id,e.contest_name,e.contest_year,e.role_name from item_rows ir
 join public.syllabus_topics t on t.id=ir.topic_id and t.content_status='current'
 join public.syllabus_editions e on e.id=t.edition_id and e.status='active'
 join public.content_sources s on s.url=ir.item->>'source_url' and s.status='vigente' and s.is_official=true
)
insert into public.curated_question_catalog(source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,verified_at,law_version_checked_at,state,career_category,role_type,tested_topic)
select source_id,topic_id,'norte:study:'||slug||':'||ord,contest_name,contest_year,role_name,'AUTORAL',discipline,topic_label,item->>'q',case when (item->>'a')::boolean then 'C' else 'E' end,item->>'why',jsonb_build_array(jsonb_build_object('url',item->>'source_url','material_slug',slug,'practice_index',ord)),'média','active',true,now(),now(),state,case when state='RO' then 'Auditoria' else 'Policial' end,case when state='RO' then 'Auditor' else 'Policial' end,topic_label
from eligible on conflict (source_id,external_item_key) do nothing;
do $verify$ begin
if (select count(*) from public.study_materials where slug in ('legislacao-crimes-ciberneticos-atualizado-2026','legislacao-marco-civil-internet-2026','legislacao-lgpd-atualizada-2026') and content_status='active' and jsonb_array_length(quiz)=8) <> 3 then raise exception 'Expected three active modules with eight questions each'; end if;
if (select count(*) from public.curated_question_catalog where external_item_key like 'norte:study:legislacao-%' and content_status='active' and is_original) <> 24 then raise exception 'Expected 24 active authored questions'; end if;
end $verify$;
commit;
